export function dynamicGraphSynthesizer(graphData, agentOutputs) {
  const weightedVotes = agentOutputs.map(output => {
    return {
      node: output.node,
      weight: output.confidence
    };
  });

  const synthesizedGraph = graphData.map(node => {
    const votes = weightedVotes.filter(vote => vote.node === node.id);
    const totalWeight = votes.reduce((acc, v) => acc + v.weight, 0);
    return {
      ...node,
      confidence: totalWeight / votes.length
    };
  });

  return synthesizedGraph;
}